#include "mcuboot_updater.h"

#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/storage/flash_map.h>
#include <zephyr/sys/crc.h>
#include <zephyr/sys/reboot.h>

LOG_MODULE_REGISTER(mcuboot_upd, LOG_LEVEL_INF);

/* Marvell firmware structures as generated by axf2firmware */
#define MRVL_FW_MAGIC_STR 0x4C56524D /* "MRVL" in little-endian */
#define MRVL_FW_MAGIC_SIG 0x2E9CF17B

struct img_hdr {
    uint32_t magic_str;
    uint32_t magic_sig;
    uint32_t time;
    uint32_t seg_cnt;
    uint32_t entry;
} __attribute__((packed));

struct seg_hdr {
    uint32_t type;
    uint32_t offset;
    uint32_t len;
    uint32_t laddr;
    uint32_t crc;
} __attribute__((packed));

/* Marvell soft_crc32: reflected CRC32 polynomial 0xEDB88320 with initial 0 and
 * no inversion */
static uint32_t calc_mrvl_crc32(const uint8_t* data, size_t len) {
    static const uint32_t table[16] = {
        0x00000000U, 0x1db71064U, 0x3b6e20c8U, 0x26d930acU,
        0x76dc4190U, 0x6b6b51f4U, 0x4db26158U, 0x5005713cU,
        0xedb88320U, 0xf00f9344U, 0xd6d6a3e8U, 0xcb61b38cU,
        0x9b64c2b0U, 0x86d3d2d4U, 0xa00ae278U, 0xbdbdf21cU,
    };

    uint32_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        uint8_t byte = data[i];
        crc = (crc >> 4) ^ table[(crc ^ byte) & 0x0f];
        crc = (crc >> 4) ^ table[(crc ^ ((uint32_t)byte >> 4)) & 0x0f];
    }
    return crc;
}

int mcuboot_validate_image(const uint8_t* data, size_t len) {
    if (len < sizeof(struct img_hdr) || len > MCUBOOT_MAX_IMG_SIZE) {
        LOG_ERR("Invalid image size: %zu bytes", len);
        return -EINVAL;
    }

    const struct img_hdr* ihdr = (const struct img_hdr*)data;
    if (ihdr->magic_str != MRVL_FW_MAGIC_STR) {
        LOG_ERR("Invalid magic string: 0x%08x (expected 0x%08x)",
                ihdr->magic_str, MRVL_FW_MAGIC_STR);
        return -EBADMSG;
    }
    if (ihdr->magic_sig != MRVL_FW_MAGIC_SIG) {
        LOG_ERR("Invalid magic signature: 0x%08x (expected 0x%08x)",
                ihdr->magic_sig, MRVL_FW_MAGIC_SIG);
        return -EBADMSG;
    }

    if (ihdr->seg_cnt == 0 || ihdr->seg_cnt > 16) {
        LOG_ERR("Invalid segment count: %u", ihdr->seg_cnt);
        return -EBADMSG;
    }

    size_t min_hdr_size =
        sizeof(struct img_hdr) + (ihdr->seg_cnt * sizeof(struct seg_hdr));
    if (len < min_hdr_size) {
        LOG_ERR("Image truncated before segment headers (%zu < %zu)", len,
                min_hdr_size);
        return -EBADMSG;
    }

    const struct seg_hdr* shdrs =
        (const struct seg_hdr*)(data + sizeof(struct img_hdr));
    for (uint32_t i = 0; i < ihdr->seg_cnt; i++) {
        if (shdrs[i].offset + shdrs[i].len > len) {
            LOG_ERR("Segment %u extends past end of image (%u + %u > %zu)", i,
                    shdrs[i].offset, shdrs[i].len, len);
            return -EBADMSG;
        }

        uint32_t computed_crc =
            calc_mrvl_crc32(data + shdrs[i].offset, shdrs[i].len);
        if (computed_crc != shdrs[i].crc) {
            LOG_ERR("Segment %u CRC mismatch (calc 0x%08x != hdr 0x%08x)", i,
                    computed_crc, shdrs[i].crc);
            return -EBADMSG;
        }
    }

    LOG_INF("MCUboot image validated successfully: %zu bytes, %u segments", len,
            ihdr->seg_cnt);
    return 0;
}

static uint8_t* s_ram_buf = NULL;
static size_t s_ram_buf_len = 0;

void mcuboot_updater_reset(void) {
    if (s_ram_buf) {
        free(s_ram_buf);
        s_ram_buf = NULL;
    }
    s_ram_buf_len = 0;
}

void mcuboot_updater_abort(void) {
    LOG_WRN("Aborting MCUboot update");
    mcuboot_updater_reset();
}

int mcuboot_updater_process_chunk(const uint8_t* data, size_t len) {
    if (len == 0) {
        return 0;
    }
    if (s_ram_buf_len + len > MCUBOOT_MAX_IMG_SIZE) {
        LOG_ERR("Chunk exceeds MCUboot partition capacity (%zu + %zu > %d)",
                s_ram_buf_len, len, MCUBOOT_MAX_IMG_SIZE);
        return -ENOMEM;
    }

    uint8_t* new_buf = realloc(s_ram_buf, s_ram_buf_len + len);
    if (!new_buf) {
        LOG_ERR("Failed to allocate RAM buffer for chunk (%zu bytes)",
                s_ram_buf_len + len);
        return -ENOMEM;
    }
    s_ram_buf = new_buf;
    memcpy(s_ram_buf + s_ram_buf_len, data, len);
    s_ram_buf_len += len;
    return 0;
}

int mcuboot_updater_complete(void) {
    if (!s_ram_buf || s_ram_buf_len == 0) {
        LOG_ERR("No image data received");
        mcuboot_updater_reset();
        return -ENODATA;
    }

    int rc = mcuboot_validate_image(s_ram_buf, s_ram_buf_len);
    if (rc != 0) {
        LOG_ERR("Validation failed (%d); rejecting update", rc);
        mcuboot_updater_reset();
        return rc;
    }

#if defined(CONFIG_FLASH_MAP) && FIXED_PARTITION_EXISTS(boot_partition)
    const struct flash_area* fa = NULL;
    rc = flash_area_open(PARTITION_ID(boot_partition), &fa);
    if (rc != 0) {
        LOG_ERR("Failed to open boot_partition: %d", rc);
        mcuboot_updater_reset();
        return rc;
    }

    size_t erase_size = ROUND_UP(s_ram_buf_len, 4096);
    if (erase_size > fa->fa_size) {
        erase_size = fa->fa_size;
    }

    LOG_INF("Flashing new MCUboot image to flash (%zu bytes, erasing %zu)...",
            s_ram_buf_len, erase_size);

    k_sched_lock();

    rc = flash_area_erase(fa, 0, erase_size);
    if (rc != 0) {
        k_sched_unlock();
        LOG_ERR("Flash erase failed: %d", rc);
        flash_area_close(fa);
        mcuboot_updater_reset();
        return rc;
    }

    rc = flash_area_write(fa, 0, s_ram_buf, s_ram_buf_len);
    if (rc != 0) {
        k_sched_unlock();
        LOG_ERR("Flash write failed: %d", rc);
        flash_area_close(fa);
        mcuboot_updater_reset();
        return rc;
    }

    k_sched_unlock();

    /* Read back and verify */
    uint8_t verify_chunk[256];
    size_t verified = 0;
    while (verified < s_ram_buf_len) {
        size_t to_read = sizeof(verify_chunk);
        if (verified + to_read > s_ram_buf_len) {
            to_read = s_ram_buf_len - verified;
        }
        rc = flash_area_read(fa, verified, verify_chunk, to_read);
        if (rc != 0 ||
            memcmp(verify_chunk, s_ram_buf + verified, to_read) != 0) {
            LOG_ERR("Flash verification mismatch at offset %zu!", verified);
            flash_area_close(fa);
            mcuboot_updater_reset();
            return -EIO;
        }
        verified += to_read;
    }

    flash_area_close(fa);
    LOG_INF("MCUboot verified in flash successfully!");
    mcuboot_updater_reset();
    return 0;
#else
    LOG_INF("Simulated MCUboot update complete (no flash_map on host)");
    mcuboot_updater_reset();
    return 0;
#endif
}
